import Component from 'flarum/common/components/Component';
import Link from 'flarum/common/components/Link';
import app from 'flarum/forum/app';
export default class TicketList extends Component {
  view() {
    const tickets = app.store.all('tickets');
    if (!tickets.length) {
      return m("div", {
        className: "SupportPage-empty"
      }, app.translator.trans('cengizkemec-support.forum.no_tickets'));
    }
    return m("ul", {
      className: "TicketList"
    }, tickets.map(ticket => m("li", {
      key: ticket.id(),
      className: "TicketList-item"
    }, m(Link, {
      href: app.route('support.ticket', {
        id: ticket.id()
      })
    }, m("strong", null, ticket.subject()), m("span", {
      className: `TicketStatus TicketStatus--${ticket.status()}`
    }, app.translator.trans(`cengizkemec-support.forum.status.${ticket.status()}`)), m("span", {
      className: "TicketPriority"
    }, ticket.priority())))));
  }
}
flarum.reg.add('cengizkemec-support-tickets', 'forum/components/TicketList', TicketList);